input.command:
cat > package.json <<'EOF'
{
  "name": "acme-design-tokens",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "validate": "node -e \"for (const f of ['tokens.json','tokens-system.json']) JSON.parse(require('fs').readFileSync(f,'utf8'))\""
  },
  "devDependencies": {
    "klar-cli": "3.0.0"
  }
}
EOF
npm run validate; echo exit=$?
echo '{bad' > /tmp/x.json; cp tokens.json $TMPDIR/tk.bak 2>/dev/null; cp tokens.json ../tk.bak; echo '{bad' > tokens.json; npm run validate 2>&1 | tail -5; echo exit=${PIPESTATUS[0]}; mv ../tk.bak tokens.json; rm /tmp/x.json; npm run validate; echo exit=$?; git status --short

